def solve(grid):
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # count non‑zero values
    cnt = Counter()
    for r in grid:
        for v in r:
            if v != 0:
                cnt[v] += 1

    # ----- find the rectangular border (frame) -----
    border_color = None
    border_min_r = border_max_r = border_min_c = border_max_c = None

    # try colors in order of decreasing frequency
    for color in sorted(cnt.keys(), key=lambda c: -cnt[c]):
        # compute bounding box for this color
        min_r, max_r = rows, -1
        min_c, max_c = cols, -1
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == color:
                    if i < min_r: min_r = i
                    if i > max_r: max_r = i
                    if j < min_c: min_c = j
                    if j > max_c: max_c = j
        # check whether this bounding box is a proper frame (border cells are color, interior is 0)
        ok = True
        for i in range(min_r, max_r + 1):
            for j in range(min_c, max_c + 1):
                if i == min_r or i == max_r or j == min_c or j == max_c:
                    if grid[i][j] != color:
                        ok = False
                        break
                else:
                    if grid[i][j] != 0:
                        ok = False
                        break
            if not ok:
                break
        if ok:
            border_color = color
            border_min_r, border_max_r = min_r, max_r
            border_min_c, border_max_c = min_c, max_c
            break

    if border_color is None:   # fallback (should not happen for given tasks)
        border_color = 2
        # locate border 2
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == border_color:
                    if border_min_r is None:
                        border_min_r = border_max_r = i
                        border_min_c = border_max_c = j
                    else:
                        if i < border_min_r: border_min_r = i
                        if i > border_max_r: border_max_r = i
                        if j < border_min_c: border_min_c = j
                        if j > border_max_c: border_max_c = j

    # ----- find the other coloured shape (the one that is not the border) -----
    shape_color = None
    for c in cnt.keys():
        if c != border_color:
            if shape_color is None or cnt[c] < cnt[shape_color]:
                shape_color = c

    if shape_color is None:               # no secondary shape – just crop the border
        new_h = border_max_r - border_min_r + 1
        new_w = border_max_c - border_min_c + 1
        return [[border_color] * new_w for _ in range(new_h)]

    # bounding box of the shape
    s_min_r = s_max_r = s_min_c = s_max_c = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == shape_color:
                if s_min_r is None:
                    s_min_r = s_max_r = i
                    s_min_c = s_max_c = j
                else:
                    if i < s_min_r: s_min_r = i
                    if i > s_max_r: s_max_r = i
                    if j < s_min_c: s_min_c = j
                    if j > s_max_c: s_max_c = j

    shape_h = s_max_r - s_min_r + 1
    shape_w = s_max_c - s_min_c + 1

    # size of the new (cropped) grid = border size
    new_h = border_max_r - border_min_r + 1
    new_w = border_max_c - border_min_c + 1

    interior_h = new_h - 2
    interior_w = new_w - 2
    scale = interior_h // shape_h          # integer scaling factor (same for width)

    # create result: border colour everywhere
    result = [[border_color] * new_w for _ in range(new_h)]

    # clear interior to zeros
    for i in range(1, new_h - 1):
        for j in range(1, new_w - 1):
            result[i][j] = 0

    # extract the shape matrix
    shape_mat = [[grid[s_min_r + i][s_min_c + j] for j in range(shape_w)] for i in range(shape_h)]

    # embed the scaled shape into the interior
    for i in range(shape_h):
        for j in range(shape_w):
            val = shape_mat[i][j]
            if val != 0:
                start_i = 1 + i * scale
                end_i = start_i + scale
                start_j = 1 + j * scale
                end_j = start_j + scale
                for ii in range(start_i, end_i):
                    for jj in range(start_j, end_j):
                        result[ii][jj] = val

    return result

